document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("calorie-needs-form"),n=document.getElementById("calorie-needs-result");e&&e.addEventListener("submit",function(t){t.preventDefault();const i=e.gender.value,o=+e.age.value,a=+e.height.value,l=+e.weight.value,r=e["weight-unit"].value,s=+e.activity.value,d=e.goal.value,p="lbs"===r?.453592*l:l,g="lbs"===r?700:300;if(!i||o<=0||a<=0||l<=0||!s)return n.innerHTML='<p style="color:red;">Please fill in all fields with valid values.</p>',void 0;if(l<30||l>g)return n.innerHTML=`<p style="color:red;">Please enter a valid weight (30-${g} ${r}).</p>`,void 0;const c="male"===i?10*p+6.25*a-5*o+5:10*p+6.25*a-5*o-161,u=c*s;let v,f,y,m=u,h="",b=0;"loss"===d?(b=Math.max(300,.15*u),m=u-b,h="weight loss"):"gain"===d?(b=Math.max(200,.1*u),m=u+b,h="muscle gain"):h="weight maintenance","loss"===d?(v=.35,f=.25,y=.4):"gain"===d?(v=.3,f=.25,y=.45):(v=.25,f=.3,y=.45);const x=m*v,$=m*f,w=m*y,M=Math.round(x/4),z=Math.round($/9),k=Math.round(w/4),T=e=>`${Math.round(e).toLocaleString("en-US")} kcal`;let C=`\n      <div style="background:#f8f9fa;padding:20px;border-radius:8px;margin:20px 0;">\n        <h3 style="color:#157aff;margin-top:0;">Your Daily Calorie Needs</h3>\n        \n        <div style="background:white;padding:15px;border-radius:6px;margin:15px 0;">\n          <p><strong>Weight:</strong> ${l} ${r} ${"lbs"===r?`(${p.toFixed(1)} kg)`:""}</p>\n          <p><strong>BMR (Basal Metabolic Rate):</strong> <span style="color:#157aff;">${T(c)}</span></p>\n          <p><strong>TDEE (Total Daily Energy Expenditure):</strong> <span style="color:#157aff;">${T(u)}</span></p>\n          <p><strong>Target Calories (${h}):</strong> <span style="color:#28a745;font-size:1.2em;font-weight:bold;">${T(m)}</span></p>`;"loss"===d?C+=`<p><strong>Daily Calorie Deficit:</strong> <span style="color:#dc3545;">${T(b)}</span></p>\n      <p style="color:#6c757d;font-size:0.9em;">This should result in approximately 0.5-1 lb weight loss per week.</p>`:"gain"===d&&(C+=`<p><strong>Daily Calorie Surplus:</strong> <span style="color:#28a745;">${T(b)}</span></p>\n      <p style="color:#6c757d;font-size:0.9em;">Combined with strength training, this supports lean muscle growth.</p>`),C+=`\n        </div>\n\n        <div style="background:white;padding:15px;border-radius:6px;">\n          <h4 style="margin-top:0;">Recommended Macronutrient Breakdown</h4>\n          <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;">\n            <div style="text-align:center;padding:10px;background:#e3f2fd;border-radius:4px;">\n              <div style="font-weight:bold;color:#1976d2;">Protein</div>\n              <div style="font-size:1.1em;">${M}g</div>\n              <div style="color:#666;font-size:0.9em;">${T(x)}</div>\n              <div style="color:#666;font-size:0.8em;">${Math.round(100*v)}%</div>\n            </div>\n            <div style="text-align:center;padding:10px;background:#fff3e0;border-radius:4px;">\n              <div style="font-weight:bold;color:#f57c00;">Fats</div>\n              <div style="font-size:1.1em;">${z}g</div>\n              <div style="color:#666;font-size:0.9em;">${T($)}</div>\n              <div style="color:#666;font-size:0.8em;">${Math.round(100*f)}%</div>\n            </div>\n            <div style="text-align:center;padding:10px;background:#e8f5e8;border-radius:4px;">\n              <div style="font-weight:bold;color:#388e3c;">Carbs</div>\n              <div style="font-size:1.1em;">${k}g</div>\n              <div style="color:#666;font-size:0.9em;">${T(w)}</div>\n              <div style="color:#666;font-size:0.8em;">${Math.round(100*y)}%</div>\n            </div>\n          </div>\n        </div>\n\n        <div style="background:#fff3cd;padding:15px;border-radius:6px;margin-top:15px;">\n          <h4 style="margin-top:0;color:#856404;">Important Notes</h4>\n          <ul style="margin:0;color:#856404;">\n            <li>These are estimates based on scientific formulas</li>\n            <li>Individual metabolism can vary by ±15%</li>\n            <li>Track your progress and adjust as needed</li>\n            <li>Consult a healthcare professional for personalized advice</li>\n          </ul>\n        </div>\n      </div>\n    `,n.innerHTML=C})});